package render

import (
	"fmt"
	"strings"

	"github.com/dada200409/egressvpn/internal/config"
)

// verifyScript is what you run on the server after apply.sh. Everything in it is
// a factual check about THIS host, because none of it can be established by
// rendering on a workstation: kernel module presence, nft syntax acceptance,
// strongSwan plugin availability, and whether the chained path really leaks
// through B rather than A.
func verifyScript(c *config.Config) string {
	var b strings.Builder
	b.WriteString(`#!/bin/sh
# generated by egressvpn - post-deploy verification, run on server A as root
set -u
fails=0
ok()   { printf 'PASS  %s\n' "$1"; }
bad()  { printf 'FAIL  %s\n' "$1"; fails=$((fails+1)); }

`)
	b.WriteString(`# --- hop 1: IKEv2 ---
if [ -d /sys/module/xfrm_algo ]; then ok "xfrm present"; else ok "xfrm is builtin on most kernels (non-fatal)"; fi
command -v swanctl >/dev/null && ok "swanctl installed" || bad "swanctl not installed"

`)
	b.WriteString(`# EAP-MSCHAPv2 is the only account/password method macOS IKEv2 speaks here, and
# two different things can be wrong: the package is missing, or it is installed but
# charon never loaded it (Debian sets load_modular = yes, and ships no load snippet
# for this plugin, so it sits on disk unused). Both look identical from the client:
# IKE_AUTH fails with "no EAP method available". The algorithm listing cannot see
# this - it only reports crypto - so ask the running daemon what it actually
# mapped in.
if [ -e /usr/lib/ipsec/plugins/libstrongswan-eap-mschapv2.so ]; then
  ok "eap-mschapv2 installed"
else
  bad "eap-mschapv2 plugin not found (apt install libcharon-extauth-plugins; on <=20.04 libcharon-extra-plugins)"
fi

CHARON_PID=$(pgrep -x charon | head -1)
if [ -z "$CHARON_PID" ]; then
  bad "charon is not running"
elif grep -q libstrongswan-eap-mschapv2.so "/proc/$CHARON_PID/maps" 2>/dev/null; then
  ok "charon has loaded eap-mschapv2"
else
  bad "charon has NOT loaded eap-mschapv2 - needs charon.plugins.eap-mschapv2.load = yes (apply.sh installs /etc/strongswan.d/egressvpn.conf) and a daemon restart"
fi

`)
	// swanctl only reads /etc/swanctl/swanctl.conf and its includes, so a missing
	// conf.d include means the daemon is up and running an entirely different config
	fmt.Fprintf(&b, `# --- did our config reach charon? ---
if swanctl --list-conns 2>/dev/null | grep -qF -- "%s"; then
  ok "connections loaded"
else
  bad "no connection '%s' loaded - is /etc/swanctl/conf.d/egressvpn.conf included by /etc/swanctl/swanctl.conf?"
fi

`, c.Users[0].Name, c.Users[0].Name)
	b.WriteString(`# --- ruleset compiles? (same check apply.sh does, re-run for confidence) ---
if nft -c -f /etc/nftables.d/egress.nft 2>/dev/null; then
  ok "nft ruleset compiles"
else
  bad "nft ruleset does NOT compile - deploy would leave A forwarding nothing"
fi

`)
	for _, u := range c.Upstreams {
		fmt.Fprintf(&b, "# --- hop 2: %s (transport %s) ---\n", u.Name, u.Transport)
		// These are backtick strings, so a trailing \n here is two literal
		// characters, not a newline: the next check would be glued onto this one and
		// the generated script would not parse.
		if u.OverTCP() {
			// There is no handshake to inspect on an ssh link, so ask the two
			// questions that actually matter: is the device there, and does the far
			// end answer over it.
			fmt.Fprintf(&b, "ip -br link show %s 2>/dev/null | grep -q UP && ok \"%s (tcp) is up\" || bad \"%s is missing or DOWN - journalctl -u egressvpn-hop2-%s\"\n", u.Interface, u.Interface, u.Interface, u.Name)
			fmt.Fprintf(&b, "systemctl is-active --quiet egressvpn-hop2-%s.service && ok \"hop-2 unit egressvpn-hop2-%s is running\" || bad \"hop-2 unit egressvpn-hop2-%s is not running (link dies with it and relay faces would egress via A)\"\n", u.Name, u.Name, u.Name)
			// B's end is a forced ssh command: it configures its tunnel device only
			// after the link has been re-established, so right after apply.sh
			// restarts the hop-2 unit this fails for a few seconds on a healthy
			// chain. Give the far end time instead of reporting a false FAIL.
			fmt.Fprintf(&b, "i=0\nwhile [ $i -lt 15 ] && ! ping -c 1 -W 2 %s >/dev/null 2>&1; do i=$((i+1)); sleep 1; done\nping -c 1 -W 2 %s >/dev/null 2>&1 && ok \"hop-2 peer %s answers over %s\" || bad \"no reply from %s via %s after 15s - the forced command on B did not configure its end\"\n", cidrIP(u.RemoteTunnelIP), cidrIP(u.RemoteTunnelIP), cidrIP(u.RemoteTunnelIP), u.Interface, cidrIP(u.RemoteTunnelIP), u.Interface)
		} else {
			fmt.Fprintf(&b, "wg show %s >/dev/null 2>&1 && ok \"%s is up\" || bad \"%s is not configured\"\n", u.Interface, u.Interface, u.Interface)
			fmt.Fprintf(&b, "wg show %s latest-handshakes 2>/dev/null | awk '{if ($2+0 == 0) exit 1}' && ok \"%s has a live handshake\" || bad \"%s has NEVER handshaked - endpoint unreachable or keys mismatched\"\n", u.Interface, u.Interface, u.Interface)
		}
		fmt.Fprintf(&b, "ip rule show | grep -q \"lookup 100\" && ok \"policy routing installed\" || bad \"ip rule missing: relay faces would egress via A\"\n\n")
	}
	// The XFRM plumbing is the difference between a tunnel that forwards and a
	// tunnel that eats the host's own traffic, and none of it is visible in the
	// IKE log: charon reports a clean CHILD_SA either way.
	for _, face := range c.Faces {
		iface := xfrmIface(face.Name)
		fmt.Fprintf(&b, `if ip -br link show %s 2>/dev/null | grep -q UP; then
  ok "xfrm device %s is up"
else
  bad "xfrm device %s missing or DOWN (apply.sh did not run, or the kernel has no xfrm_interface) - client traffic has nowhere to enter"
fi
ip route show 2>/dev/null | grep -q "dev %s" && ok "pool %s routes via %s" || bad "no route into %s: the face's traffic never reaches its SA (egressvpn-routes.sh rebuilds it within a minute - journalctl -u egressvpn-routes.service)"
sysctl -n net.ipv4.conf.%s.forwarding 2>/dev/null | grep -q 1 && ok "%s forwards (decrypted packets arrive with iif=%s)" || bad "net.ipv4.conf.%s.forwarding is off: FORWARD never sees the client's packets"

`, iface, iface, iface, iface, face.Pool, iface, iface, iface, iface, iface, iface)
	}
	// A deployment that is correct on disk and missing in the kernel is the failure
	// mode this whole host has hit twice: the pool route is pruned by an interface
	// flap, and nothing re-adds it. So check the thing that re-adds it.
	b.WriteString(`# --- does the route keeper exist and is it armed? ---
if [ -x /usr/local/sbin/egressvpn-routes.sh ]; then
  ok "route reconciler installed"
else
  bad "/usr/local/sbin/egressvpn-routes.sh is missing - a flap silently blacks out a face"
fi
if systemctl is-active --quiet egressvpn-routes.timer; then
  ok "route timer is armed"
else
  bad "egressvpn-routes.timer is not running: systemctl enable --now egressvpn-routes.timer"
fi

`)
	// Rule-count check. The kernel table is the union of everything ever loaded, and
	// the deploy that "looked fine" here was sitting under hand-inserted rules: an
	// `ip saddr <pool> drop` probe added at the top of the chain ate every forwarded
	// client packet, so the client kept its access to A's own panel (answered by
	// INPUT, never forwarded) and lost the internet, with nothing in any log. Counting
	// the rules per pool is the cheap way to see the live chain is not this file.
	for _, face := range c.Faces {
		expected := 2 + len(c.Server.LAN)
		fmt.Fprintf(&b, `live=$(nft list chain inet egressvpn forward 2>/dev/null | grep -c "saddr %s")
if [ "$live" -eq %d ]; then
  ok "face %s: %d forward rules, exactly as generated"
else
  bad "face %s: $live forward rules in the kernel, expected %d - extra rules (or a hand-inserted drop above the accept); fix by re-running: nft -f /etc/nftables.d/egress.nft"
fi

`, face.Pool, expected, face.Name, expected, face.Name, expected)
	}
	// The clamp can be right in the file and wrong in the kernel, and the wrong
	// version is quiet: an unconditional "tcp option maxseg size set N" raises the
	// advertised MSS above the client's tunnel MTU instead of lowering it, so every
	// large segment is dropped at the client and only ICMP survives. Measured here:
	// clamp 1340 against a 1280-byte ipsec0 = 100% loss above 1280 bytes.
	for _, face := range c.Faces {
		fmt.Fprintf(&b, `live=$(nft list chain inet egressvpn mssclamp 2>/dev/null | grep -c "%s")
if [ "$live" -eq 2 ]; then
  ok "face %s: MSS clamp installed in both directions"
else
  bad "face %s: $live mssclamp rules in the kernel, expected 2 (client SYN + remote SYN-ACK); re-run: nft -f /etc/nftables.d/egress.nft"
fi

`, face.Pool, face.Name, face.Name)
	}
	b.WriteString(`raise=$(nft list chain inet egressvpn mssclamp 2>/dev/null | grep 'tcp flags' | grep -v 'maxseg size [0-9]*-' | grep -c 'size set')
if [ "$raise" -eq 0 ]; then
  ok "every clamp matches a range: it can only lower the MSS"
else
  bad "$raise clamp rule(s) set MSS with no range match - they RAISE it past the client's tunnel MTU and black-hole large packets; re-run: nft -f /etc/nftables.d/egress.nft"
fi

`)
	// The xfrmi MTU is the server half of the tunnel's path MTU; if it disagrees
	// with the clamp the mismatch shows up as throughput, not as an error.
	for _, face := range c.Faces {
		iface := xfrmIface(face.Name)
		fmt.Fprintf(&b, `if ip link show %s 2>/dev/null | head -1 | grep -q "mtu %d "; then
  ok "%s carries the tunnel MTU %d"
else
  bad "%s MTU is not the tunnel MTU %d - segments the device cannot carry are dropped without a word; re-run apply.sh"
fi

`, iface, c.Tuning.TunnelMtu, iface, c.Tuning.TunnelMtu, iface, c.Tuning.TunnelMtu)
	}
	b.WriteString(`# charon must not install routes for a 0/0 remote selector: that becomes a default
# route into the tunnel device and takes the host offline along with the client.
# install_routes lives in the same file as the plugin loads, so check both - an
# operator edit that "only changes one key" there has taken a live server's EAP out.
if grep -Eq 'install_routes[[:space:]]*=[[:space:]]*no' /etc/strongswan.d/egressvpn.conf; then
  ok "charon.install_routes = no"
else
  bad "charon.install_routes = no missing from /etc/strongswan.d/egressvpn.conf"
fi
if grep -Eq 'eap-mschapv2[[:space:]]*\{' /etc/strongswan.d/egressvpn.conf; then
  ok "strongswan.d override still carries the plugin loads"
else
  bad "/etc/strongswan.d/egressvpn.conf no longer carries the plugin loads - re-render it or clients fail at EAP"
fi

# --- the claim that matters: what IP does a tunnel client actually see? ---
# connect as a relay-face user, then from that session run:
#     curl -s https://ifconfig.me
# it must return B's public address, not A's. If it returns A's, the kill switch
# is not doing its job and your users' real IP is leaving via A.
printf '\nMANUAL  confirm egress IP for a relay-face client matches B, not A\n'
printf 'MANUAL  on B, confirm no client-pool address ever appears in its logs\n'

if [ "$fails" -eq 0 ]; then
  printf '\nall automated checks passed\n'
else
  printf '\n%s check(s) failed\n' "$fails"
  exit 1
fi
`)
	return b.String()
}
